 48→func (k *Kiro) Bootstrap() error {
 49→	// kiro-cli-chat is the standalone binary that supports headless SIGV4 auth.
 50→	// The desktop app wrapper (kiro-cli) ignores AMAZON_Q_SIGV4 and always
 51→	// forces browser OAuth, so E2E tests must use kiro-cli-chat.
 52→	if os.Getenv("CI") == "" {
 53→		return nil
 54→	}
 55→
 56→	if isTruthyEnvValue(os.Getenv("AMAZON_Q_SIGV4")) {
 57→		if err := validateKiroSIGV4Inputs(
 58→			os.Getenv("AWS_REGION"),
 59→			os.Getenv("AWS_ACCESS_KEY_ID"),
 60→			os.Getenv("AWS_SECRET_ACCESS_KEY"),
 61→		); err != nil {
 62→			return fmt.Errorf("kiro-cli-chat sigv4 auth check failed: %w", err)
 63→		}
 64→		return nil
 65→	}
 66→
 67→	// Verify login status — fail fast if not authenticated.
 68→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 69→	defer cancel()
 70→	cmd := exec.CommandContext(ctx, "kiro-cli-chat", "whoami", "-f", "json")
 71→	out, err := cmd.CombinedOutput()
 72→	if err != nil {
 73→		return fmt.Errorf(
 74→			"kiro-cli-chat auth check failed (run `kiro-cli-chat login --use-device-flow`): %s",
 75→			strings.TrimSpace(string(out)),
 76→		)
 77→	}
 78→	if err := validateKiroWhoamiJSON(out); err != nil {
 79→		return fmt.Errorf("kiro-cli-chat auth check failed: %w", err)
 80→	}
 81→	return nil
 82→}
 83→
 84→func isTruthyEnvValue(v string) bool {
 85→	value := strings.TrimSpace(v)
 86→	if value == "" {
 87→		return false
 88→	}
 89→	lower := strings.ToLower(value)
 90→	return lower != "0" && lower != "false"
 91→}
 92→
 93→func validateKiroSIGV4Inputs(region, accessKeyID, secretAccessKey string) error {
 94→	if strings.TrimSpace(region) == "" {
 95→		return errors.New("AWS_REGION is required when AMAZON_Q_SIGV4 is enabled")
 96→	}
 97→	if strings.TrimSpace(accessKeyID) == "" {
 98→		return errors.New("AWS_ACCESS_KEY_ID is required when AMAZON_Q_SIGV4 is enabled")
 99→	}
100→	if strings.TrimSpace(secretAccessKey) == "" {
101→		return errors.New("AWS_SECRET_ACCESS_KEY is required when AMAZON_Q_SIGV4 is enabled")
102→	}
103→	return nil
104→}
105→
106→func validateKiroWhoamiJSON(out []byte) error {
107→	var response struct {
108→		Account json.RawMessage `json:"account"`
109→	}
110→
111→	if err := json.Unmarshal(out, &response); err != nil {
112→		return fmt.Errorf("invalid whoami JSON: %w", err)
113→	}
114→	if len(response.Account) == 0 {
115→		return errors.New("account is missing")
116→	}
117→	if strings.EqualFold(strings.TrimSpace(string(response.Account)), "null") {
118→		return errors.New("account is null")
119→	}
120→	return nil
121→}
