123→func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
124→	cfg := &runConfig{}
125→	for _, o := range opts {
126→		o(cfg)
127→	}
128→
129→	timeout := 2 * time.Minute
130→	if cfg.PromptTimeout > 0 {
131→		timeout = cfg.PromptTimeout
132→	}
133→	cmdCtx, cancel := context.WithTimeout(ctx, timeout)
134→	defer cancel()
135→
136→	// --no-interactive: runs a single prompt and exits; SIGV4 env vars
137→	// propagate naturally (no tmux env forwarding needed).
138→	// --trust-all-tools: auto-approve tool use (equivalent to -a in interactive mode).
139→	// --agent entire: activates the agent profile that contains our hooks.
140→	args := []string{"chat", "--no-interactive", "--trust-all-tools", "--agent", "entire"}
141→	if cfg.Model != "" {
142→		args = append(args, "--model", cfg.Model)
143→	}
144→	args = append(args, prompt)
145→
146→	// Build display args with quoted prompt for logging.
147→	displayArgs := make([]string, len(args))
148→	copy(displayArgs, args)
149→	displayArgs[len(displayArgs)-1] = fmt.Sprintf("%q", prompt)
150→
151→	cmd := exec.CommandContext(cmdCtx, k.Binary(), args...)
152→	cmd.Dir = dir
153→	cmd.Stdin = nil
154→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
155→	cmd.Cancel = func() error {
156→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
157→	}
158→	cmd.WaitDelay = 5 * time.Second
159→
160→	var stdout, stderr strings.Builder
161→	cmd.Stdout = &stdout
162→	cmd.Stderr = &stderr
163→
164→	err := cmd.Run()
165→	exitCode := 0
166→	if err != nil {
167→		exitErr := &exec.ExitError{}
168→		if errors.As(err, &exitErr) {
169→			exitCode = exitErr.ExitCode()
170→		} else {
171→			exitCode = -1
172→		}
173→	}
174→
175→	return Output{
176→		Command:  k.Binary() + " " + strings.Join(displayArgs, " "),
177→		Stdout:   stdout.String(),
178→		Stderr:   stderr.String(),
179→		ExitCode: exitCode,
180→	}, err
181→}
