187→// KiroSession runs each Send as a separate --no-interactive command.
188→// SIGV4 auth does not work with the interactive TUI, so this approach
189→// runs one kiro-cli-chat process per prompt (same pattern as setup-kiro-action).
190→type KiroSession struct {
191→	kiro       *Kiro
192→	dir        string
193→	ctx        context.Context
194→	lastOutput string
195→}
196→
197→func (s *KiroSession) Send(input string) error {
198→	out, err := s.kiro.RunPrompt(s.ctx, s.dir, input)
199→	s.lastOutput = out.Stdout + out.Stderr
200→	return err
201→}
202→
203→func (s *KiroSession) WaitFor(_ string, _ time.Duration) (string, error) {
204→	return s.lastOutput, nil
205→}
206→
207→func (s *KiroSession) Capture() string { return s.lastOutput }
208→func (s *KiroSession) Close() error    { return nil }
